f=sys.argv[1]; s=open(f,encoding='utf-8').read()
a0=s.index("async function day4()"); b0=s.index("Day 5: Saturday")
d=s[a0:b0]
R=[
("วันศุกร์ สะโพกซ้ายตื่นก่อนผม\\nรอยช้ำสีม่วงเท่าฝ่ามือ อยู่ในที่ที่เสื้อผ้าปิดได้ ถือว่าโชคดี","วันศุกร์ สะโพกซ้ายตื่นก่อนผม\\nรอยช้ำเท่าฝ่ามือ อยู่ในที่ที่เสื้อผ้าปิดได้"),
("\"บ่ายสองครึ่งจะมีเภสัชกรมาเยี่ยมที่บ้านนะคะ หนูแลกเวรไว้แล้ว จะกลับไปเปิดประตูให้\"\\n\"ไม่ต้องมา ผมสบายดี\" \"เขามาคุยเรื่องยาเฉยๆ ค่ะ ไม่ได้มาจับผิด\"","\"บ่ายสองครึ่งเภสัชกรจะมาเยี่ยมนะคะ หนูแลกเวรไว้แล้ว\"\\n\"ไม่ต้องมา ผมสบายดี\" \"เขาไม่ได้มาจับผิดค่ะ\""),
("ผมวางหู คนที่บอกว่าไม่ได้มาจับผิด ผมเจอมาทั้งชีวิต\\nมีการตรวจเยี่ยม ต้องเตรียมที่ตั้ง","คนที่บอกว่าไม่ได้มาจับผิด ผมเจอมาทั้งชีวิต"),
("ผมใส่เสื้อแขนยาวทับรอยช้ำ ดันลิ้นชักยาให้ปิดสนิท ซ่อนหม้อข้าวต้มไว้หลังกระติกน้ำ\\nสิ่งที่ตรวจไม่พบ ถือว่าไม่มี","ผมใส่เสื้อแขนยาว ดันลิ้นชักยาให้ปิด ซ่อนหม้อข้าวต้มหลังกระติกน้ำ\\nสิ่งที่ตรวจไม่พบ ถือว่าไม่มี"),
("ผมนั่งรอตั้งแต่เที่ยง บ่ายสองสิบห้าต้องไปห้องน้ำ\\nไม่อยากให้พวกเขามาถึงตอนผมไม่อยู่ประจำที่ ผมเลยรีบ","บ่ายสองสิบห้า ผมต้องไปห้องน้ำ\\nไม่อยากให้เขามาถึงตอนผมไม่อยู่ประจำที่ ผมเลยรีบ"),
("อาเหมยเปิดประตู คนเสื้อขาวสองคน คนหนึ่งผมหงอกแซม อีกคนยังเด็กมาก\\nผมจะนั่งตัวตรงรายงานตัว แต่ลมไม่พอจะพูดสักคำ","อาเหมยเปิดประตู คนเสื้อขาวสองคน คนหนึ่งผมหงอก อีกคนยังเด็กมาก\\nผมไม่มีลมพอจะพูดสักคำ"),
("เด็กคนนั้นเห็นผมหอบ แล้วหันไปถามอาเหมย \"คุณปู่เป็นแบบนี้บ่อยไหมครับ\"\\nอาเหมยตอบแทนผม ผมนั่งอยู่ห่างไปสองก้าว เหมือนตู้ใบหนึ่ง","เด็กคนนั้นหันไปถามอาเหมย \"คุณปู่เป็นแบบนี้บ่อยไหมครับ\"\\nอาเหมยตอบแทนผม ผมนั่งอยู่ห่างไปสองก้าว เหมือนตู้ใบหนึ่ง"),
("เภสัชกรผมหงอกแตะแขนเด็กคนนั้นเบาๆ เขาหน้าแดง แล้วหันกลับมาหาผม\\nมือผมควานหายาพ่น ได้อันสีเขียว","เภสัชกรผมหงอกแตะแขนเขาเบาๆ เขาหน้าแดง แล้วหันกลับมาหาผม\\nมือผมควานได้ยาพ่นอันสีเขียว"),
("\"อันสีฟ้าครับ ค่อยๆ\"\\nเขาไม่ได้แย่งอันสีเขียวไปจากมือผม เขาแค่ยื่นอันสีฟ้ามา แล้วรอ","\"อันสีฟ้าครับ ค่อยๆ\" เขาไม่ได้แย่งอันสีเขียวจากมือผม\\nเขาแค่ยื่นอันสีฟ้ามา แล้วรอ"),
("\"ดีมากครับ ไม่ต้องรีบ เรามีเวลาทั้งบ่าย\"\\nไม่มีใครพูดประโยคนี้กับผมมานานแล้ว หมอมีให้ผมสามนาที","\"ไม่ต้องรีบครับ เรามีเวลาทั้งบ่าย\"\\nหมอมีให้ผมสามนาที"),
("\"ผมขอแนะนำตัวใหม่นะครับ\" เขาชูบัตรให้ผมดูใกล้ๆ\\n\"ผมเป็นนักศึกษาเภสัช มากับเภสัชกรเฉิน ขอเวลาคุณปู่ราวหนึ่งชั่วโมง มาช่วยดูเรื่องยา คุณปู่อนุญาตไหมครับ\"","เขาชูบัตรให้ผมดูใกล้ๆ \"ผมเป็นนักศึกษาเภสัช มากับเภสัชกรเฉิน\\nขอเวลาราวหนึ่งชั่วโมง มาช่วยดูเรื่องยา คุณปู่อนุญาตไหมครับ\""),
("คนถือแฟ้มบางคนเปิดถุงยาหลังประตูก่อนจะทักผม บางคนพาอาเหมยไปคุยที่ระเบียง\\nบางคนลูบหัวเจ้าดำอยู่นานโดยไม่มองหน้าผม เจ้าดำชอบเขา ผมไม่","คนถือแฟ้มบางคนเปิดถุงยาก่อนจะทักผม\\nบางคนลูบหัวเจ้าดำอยู่นานโดยไม่มองหน้าผม เจ้าดำชอบเขา ผมไม่"),
("เด็กคนนั้นนั่งพื้นเหมือนเดิม เปิดสมุด แต่ยังไม่จดอะไร\\n\"ช่วงนี้เรื่องกินข้าวเป็นยังไงบ้างครับ\"","เขานั่งพื้น เปิดสมุด แต่ยังไม่จดอะไร\\n\"ช่วงนี้กินข้าวเป็นยังไงบ้างครับ\""),
("\"ห้องน้ำอยู่ไกลเหมือนกันนะครับ ผมเดินขึ้นมาสี่ชั้นยังเหนื่อยเลย คุณปู่เดินทุกวัน เก่งมากครับ\"\\n","\"ผมเดินขึ้นมาสี่ชั้นยังเหนื่อยเลย คุณปู่เดินทุกวัน เก่งมากครับ\"\\n"),
("ผมมองไปที่หน้าต่าง สะโพกซ้ายเต้นตุบๆ อยู่ใต้กางเกง\\nเด็กคนนั้นมองตามสายตาผม แล้วไม่ได้จดอะไรลงสมุด","ผมมองไปที่หน้าต่าง สะโพกเต้นตุบๆ\\nเขามองตามสายตาผม แล้วไม่ได้จดอะไร"),
("\"เรื่องที่คุณปู่เล่าวันนี้ ผมจะใช้ดูแลเรื่องยาเท่านั้นครับ ถ้าจะต้องบอกใคร ผมจะถามคุณปู่ก่อน\"\\nเขาพูดเหมือนอ่านใจผมออก หรือไม่ก็ มีคนสอนเขามาดี","\"เรื่องที่คุณปู่เล่า ผมจะใช้ดูแลเรื่องยาเท่านั้น ถ้าจะบอกใคร ผมจะถามคุณปู่ก่อนครับ\"\\nมีคนสอนเขามาดี"),
("เขาเหลือบดูสมุด แล้วถามเร็วไปหน่อย \"ทำไมคุณปู่ไม่ใช้อันสีเขียวล่ะครับ\"\\nทำไม หลังคำนี้จะตามด้วยความผิดของผมเสมอ","\"ทำไมคุณปู่ไม่ใช้อันสีเขียวล่ะครับ\"\\nทำไม หลังคำนี้จะตามด้วยความผิดของผมเสมอ"),
("เภสัชกรเฉินกระแอมเบาๆ เด็กคนนั้นวางปากกาลง\\n\"ขอโทษครับ ผมถามไม่ดี อันสีเขียว เวลาคุณปู่ใช้ รู้สึกยังไงบ้างครับ\"","เภสัชกรเฉินกระแอมเบาๆ\\n\"ขอโทษครับ ผมถามไม่ดี อันสีเขียว เวลาใช้รู้สึกยังไงบ้างครับ\""),
("\"กดแล้วไม่รู้สึกอะไร\" ผมตอบได้ทันที\\nคำถามเดียวกัน แต่คราวนี้มันเป็นคำถามจริงๆ","\"กดแล้วไม่รู้สึกอะไร\"\\nคำถามเดียวกัน แต่คราวนี้มันเป็นคำถามจริงๆ"),
("\"ก่อนจะคุยเรื่องยา ผมอยากรู้ก่อนครับ ว่าคุณปู่หวังอะไร\"\\nผมรอคำถามข้อต่อไป ไม่มี เขารอคำตอบจริงๆ","\"ก่อนคุยเรื่องยา ผมอยากรู้ว่าคุณปู่หวังอะไรครับ\"\\nเขารอคำตอบจริงๆ"),
("คนสุดท้ายที่ถามผมแบบนี้คือแม่ ที่ชิงเต่า ผมสิบห้า ผมตอบว่า อยากมีรองเท้าหนังสักคู่\\nสามเดือนต่อมา กองทัพให้รองเท้าหนังผมหนึ่งคู่ แล้วผมก็ไม่ได้กลับบ้านอีกเลย","คนสุดท้ายที่ถามแบบนี้คือแม่ ผมสิบห้า ผมตอบว่า อยากมีรองเท้าหนัง\\nสามเดือนต่อมา กองทัพให้รองเท้าหนังผมหนึ่งคู่ แล้วผมก็ไม่ได้กลับบ้านอีกเลย"),
("\"งั้นเอาเรื่องเล็กที่สุดครับ ถ้าพรุ่งนี้ทำได้หนึ่งอย่าง คุณปู่อยากทำอะไร\"\\nผมมองเจ้าดำ เด็กคนนั้นมองตาม แล้วยิ้ม","\"ถ้าพรุ่งนี้ทำได้หนึ่งอย่าง คุณปู่อยากทำอะไรครับ\"\\nผมมองเจ้าดำ เขามองตาม แล้วยิ้ม"),
("\"ภาระ\" เภสัชกรเฉินทวนช้าๆ \"ปีที่แล้วคุณปู่ลงบันไดสี่ชั้นไปหาหมอเองเก้าสิบสามครั้ง คนที่เป็นภาระทำแบบนั้นไม่ได้หรอกครับ\"","\"ปีที่แล้วคุณปู่ลงบันไดสี่ชั้นไปหาหมอเองเก้าสิบสามครั้ง\" เภสัชกรเฉินว่า \"คนที่เป็นภาระทำแบบนั้นไม่ได้หรอกครับ\""),
("เด็กคนนั้นจดตัวโต ขีดเส้นใต้สองเส้น\\n\"งั้นยาทุกตัวต่อจากนี้ ต้องตอบให้ได้ ว่ามันช่วยให้คุณปู่ลงบันไดสี่ชั้นหรือเปล่า\"","เขาจดตัวโต ขีดเส้นใต้สองเส้น\\n\"ยาทุกตัวต่อจากนี้ ต้องช่วยให้คุณปู่ลงบันไดได้\""),
("\"ผมขออนุญาตดูรอบๆ ห้องได้ไหมครับ ว่ายาเก็บไว้ตรงไหน ห้องร้อนไหม เดินสะดวกไหม\"","\"ผมขออนุญาตดูรอบๆ ห้องได้ไหมครับ\""),
("\"ได้ครับ\" เขาถอยมือกลับทันที\\nผมลองปฏิเสธดูเฉยๆ อยากรู้ว่าเขาจะหยุดจริงไหม เขาหยุดจริง","\"ได้ครับ\" เขาถอยมือทันที\\nผมแค่อยากรู้ว่าเขาจะหยุดจริงไหม เขาหยุดจริง"),
("เขายืนดูปฏิทินอยู่นาน \"มีวงหนึ่งถูกขีดฆ่า\"\\n\"วันนั้นลงบันไดไม่ไหว\" ผมตอบ ก่อนจะทันคิดว่าควรตอบไหม","เขายืนดูปฏิทินอยู่นาน ไม่ได้พูดว่าไปหาหมอเยอะเกินไป"),
("เขาไม่ได้พูดว่า ไปหาหมอเยอะเกินไป\\nเขาพูดว่า \"วงพวกนี้ คือวันที่คุณปู่ได้ออกไปเจอคน ใช่ไหมครับ\"","\"วงพวกนี้ คือวันที่คุณปู่ได้ออกไปเจอคน ใช่ไหมครับ\""),
("หม้อข้าวต้มอยู่ตรงนั้น เขาเปิดฝานิดเดียว ไม่ได้ย่นจมูก \"ต้มไว้ตั้งแต่เมื่อไรครับ\" \"…วันอาทิตย์\"\\n\"อากาศร้อนแบบนี้เชื้อโตเร็ว ต้มซ้ำก็ทำลายพิษได้ไม่หมดครับ\" ครูฝึกไม่ใช่เภสัชกร","เขาเจอหม้อข้าวต้ม \"ต้มไว้ตั้งแต่เมื่อไรครับ\" \"…วันอาทิตย์\"\\n\"อากาศร้อนแบบนี้ ต้มซ้ำก็ทำลายพิษได้ไม่หมดครับ\" ครูฝึกไม่ใช่เภสัชกร"),
("\"ต้มหม้อเล็กลง พอกินวันต่อวัน ได้ไหมครับ\"\\nเขาไม่ได้สั่งให้ผมเททิ้ง เขาถามผมว่า ได้ไหม","\"ต้มหม้อเล็กลง พอกินวันต่อวัน ได้ไหมครับ\"\\nเขาไม่ได้สั่ง เขาถามว่า ได้ไหม"),
("เขาหยิบขวดบำรุงเข่าขึ้นมาอ่านฉลาก ไม่ได้ส่ายหัว \"คุณปู่ซื้อเองเหรอครับ\"\\n\"…อย่าบอกอาเหมย\" \"ผมไม่บอกครับ ผมสัญญาไว้แล้ว\"","เขาอ่านฉลากขวดบำรุงเข่า ไม่ได้ส่ายหัว\\n\"…อย่าบอกอาเหมย\" \"ผมไม่บอกครับ\""),
("\"ตัวนี้ไม่ตีกับยาของคุณปู่ แต่หลักฐานว่าช่วยเข่ามีไม่มาก เข่าที่อยากให้ดี คุณปู่อยากเอาไปทำอะไรครับ\"\\nผมไม่ได้ตอบ ผมมองไปที่วิทยุ","\"ตัวนี้ช่วยเข่าได้ไม่มากครับ เข่าที่อยากให้ดี คุณปู่อยากเอาไปทำอะไร\"\\nผมมองไปที่วิทยุ"),
("มือเขาเอื้อมไปที่ลิ้นชัก ไหล่ผมแข็งขึ้นมาเอง\\nเขาเห็น มือหยุดกลางอากาศ \"ขอโทษครับ ลิ้นชักนี้ ผมขอเปิดได้ไหมครับ\"","มือเขาเอื้อมไปที่ลิ้นชัก ไหล่ผมแข็งขึ้นมาเอง\\nมือเขาหยุดกลางอากาศ \"ลิ้นชักนี้ ผมขอเปิดได้ไหมครับ\""),
("\"ได้ครับ ไม่เป็นไรเลย\" เขาถอยออกมา\\nผมนั่งมองลิ้นชักครู่หนึ่ง แล้วลุกไปเปิดมันเอง ไม่รู้เหมือนกันว่าทำไม","\"ได้ครับ\" เขาถอยออกมา\\nครู่หนึ่ง ผมก็ลุกไปเปิดมันเอง"),
("สิบสามซองเรียงบนผ้าห่ม เขาไม่ได้อุทาน เขาแค่เริ่มจับคู่\\n\"ซองนี้ คุณปู่อ่านออกไหมครับ ว่าให้กินตอนไหน\"","สิบสามซองเรียงบนผ้าห่ม เขาไม่ได้อุทาน\\n\"ซองนี้ คุณปู่อ่านออกไหมครับ\""),
("\"ผมอ่านไม่ออก\" ผมพูดออกไปแล้ว ก่อนจะทันอาย\\n\"ผมเองยังต้องเพ่งเลยครับ ฉลากมันเล็กเกินไป\"","\"ผมอ่านไม่ออก\"\\n\"ผมเองยังต้องเพ่งเลยครับ ฉลากมันเล็กเกินไป\""),
("\"สองซองนี้เป็นยาแก้แพ้เหมือนกัน จากคุณหมอคนละท่าน กินด้วยกันจะง่วง ทรงตัวลำบาก โดยเฉพาะตอนลุกกลางดึก\"\\nผมนึกถึงกระเบื้องเย็นๆ","\"สองซองนี้เป็นยาแก้แพ้เหมือนกัน จากหมอคนละท่าน กินด้วยกันจะง่วง ทรงตัวลำบาก\"\\nผมนึกถึงกระเบื้องเย็นๆ"),
("\"ไม่ใช่ความผิดของคุณปู่นะครับ คุณหมอแต่ละท่านมองไม่เห็นซองของอีกท่าน พวกผมมีหน้าที่มองให้เห็นครบ\"","\"ไม่ใช่ความผิดของคุณปู่ครับ หมอแต่ละท่านมองไม่เห็นซองของอีกท่าน\""),
("\"อันสีฟ้า คุณปู่กดแล้วสูดตามไม่ทันใช่ไหมครับ ยาเลยค้างที่คอ ขม แล้วก็ไอ\" เขารู้ได้ยังไง\\n\"ต่อกระบอกนี้ ยาจะรออยู่ข้างใน ลองนะครับ เขย่าก่อน สี่ห้าที\"","\"อันสีฟ้ากดแล้วสูดตามไม่ทัน ยาเลยค้างที่คอใช่ไหมครับ\"\\n\"ต่อกระบอกนี้ ยาจะรออยู่ข้างใน เขย่าก่อนครับ\""),
("ไม่ขม ไม่ไอ\\nหลายปีที่ผมสู้กับหลอดสีฟ้านี่ มันแค่ต้องการกระบอกพลาสติกหนึ่งอัน","ไม่ขม ไม่ไอ\\nมันแค่ต้องการกระบอกพลาสติกหนึ่งอัน"),
("\"อันสีเขียวที่กดแล้วไม่รู้สึกอะไร ถูกแล้วครับ มันไม่ได้มีไว้ให้รู้สึก\"\\n\"อันสีฟ้าคือหน่วยเคลื่อนที่เร็ว อันสีเขียวคือยามกะดึก ยืนเงียบๆ ทั้งคืน ถ้ายามทำงานดี แทบไม่ต้องเรียกหน่วยเคลื่อนที่เร็วเลย\"","\"อันสีฟ้าคือหน่วยเคลื่อนที่เร็ว อันสีเขียวคือยามกะดึกครับ\"\\n\"ยืนเงียบๆ ทั้งคืน ไม่ได้มีไว้ให้รู้สึก ถ้ายามทำงานดี แทบไม่ต้องเรียกหน่วยเคลื่อนที่เร็วเลย\""),
("ยามกะดึก\\nผมเป็นยามกะดึกมาสี่ปี ไม่เคยมีใครขอบใจ จนกว่าจะมีคืนที่ยามหลับ","ผมเป็นยามกะดึกมาสี่ปี\\nไม่เคยมีใครขอบใจ จนกว่าจะมีคืนที่ยามหลับ"),
("\"อันนี้ไม่ต้องเขย่าครับ ผมทำให้ดูก่อน\" หมุนฐาน… เปิดฝา… อม… กดพร้อมเริ่มสูด\\nเขามองตาผมตลอด ว่าผมตามทันไหม ไม่ได้มองนาฬิกา","\"อันนี้ไม่ต้องเขย่าครับ\" หมุนฐาน… เปิดฝา… อม… กดพร้อมเริ่มสูด\\nเขามองตาผมตลอด ไม่ได้มองนาฬิกา"),
("\"ผมไม่แน่ใจว่าอธิบายรู้เรื่องไหม รบกวนคุณปู่ทำให้ผมดูอีกรอบได้ไหมครับ คราวนี้ผมจะไม่บอกอะไรเลย\"\\nเขาไม่ได้พูดว่าจะทดสอบผม เขาพูดว่าจะตรวจว่าตัวเขาเองสอนรู้เรื่องไหม","\"ผมไม่แน่ใจว่าอธิบายรู้เรื่องไหม ทำให้ผมดูอีกรอบได้ไหมครับ\"\\nเขาไม่ได้ทดสอบผม เขาตรวจว่าตัวเองสอนรู้เรื่องไหม"),
("\"นั่นแหละครับ ที่คุณปู่เคยเจอว่ากดแล้วไม่ออก เพราะยังไม่ได้หมุน\\nตรงนี้ผมอธิบายไม่ชัดเอง จำง่ายๆ ครับ หมุน เปิด กด\"","\"นั่นแหละครับที่เคยกดแล้วไม่ออก ผมอธิบายไม่ชัดเอง\\nจำง่ายๆ ครับ หมุน เปิด กด\""),
("เขาเปิดกล่องยาเจ็ดช่อง มองอยู่ครู่หนึ่ง \"วันที่คุณอาเหมยเข้าเวรดึก เช้าวันนั้นเป็นยังไงบ้างครับ\"\\nเขาไม่ได้ถามว่า ลืมกินยาหรือเปล่า ผมมองอาเหมยที่ยืนอยู่ข้างประตู เธอยังไม่รู้อะไรเลย","เขามองกล่องยาเจ็ดช่อง \"วันที่คุณอาเหมยเข้าเวรดึก เช้าวันนั้นเป็นยังไงบ้างครับ\"\\nผมมองอาเหมยที่ยืนอยู่ข้างประตู เธอยังไม่รู้อะไรเลย"),
("\"ผมไม่อยากไปอยู่บ้านพัก ที่นั่นเขาไม่ให้เลี้ยงหมา\"\\n\"ไม่มีใครส่งคุณปู่ไปไหนทั้งนั้นครับ\" เภสัชกรเฉินพูดช้าๆ \"เรามาเพื่อให้คุณปู่อยู่ห้องนี้ได้นานที่สุด กับเจ้าดำ\"","\"ผมไม่อยากไปบ้านพัก ที่นั่นไม่ให้เลี้ยงหมา\"\\n\"เรามาเพื่อให้คุณปู่อยู่ห้องนี้ได้นานที่สุดครับ กับเจ้าดำ\""),
("อาเหมยเดินมานั่งลงข้างผม จับแขนผมไว้สองมือ\\n\"วันที่หนูเข้าเวรดึก หนูจะตั้งนาฬิกาปลุก โทรจากห้องพักค่ะ เจ็ดโมงเหมือนเดิม เหล่าหลี่รับกริ่งที่สองได้เหมือนเดิม\"","อาเหมยนั่งลงข้างผม จับแขนผมไว้สองมือ\\n\"วันเข้าเวรดึก หนูจะตั้งปลุกโทรมาเจ็ดโมง เหล่าหลี่รับกริ่งที่สองได้เหมือนเดิม\""),
("\"ก็ปกติ\" เด็กคนนั้นปิดฝากล่องเบาๆ \"ไม่เป็นไรครับ วันไหนคุณปู่อยากเล่า ผมจะมาฟัง\"\\nเขาเขียนเบอร์โทรตัวโตๆ วางไว้ข้างโทรศัพท์ เขาไม่ได้เชื่อผม และไม่ได้บังคับผม","\"ก็ปกติ\" \"วันไหนคุณปู่อยากเล่า ผมจะมาฟังครับ\"\\nเขาเขียนเบอร์โทรตัวโตๆ วางไว้ข้างโทรศัพท์ ไม่ได้เชื่อผม และไม่ได้บังคับผม"),
("\"ก่อนกลับ รบกวนคุณปู่ทวนให้ผมฟังหน่อยครับ ว่าต่อจากนี้จะทำยังไง ผมจะได้รู้ว่าพูดครบไหม\"","\"ก่อนกลับ คุณปู่ทวนให้ผมฟังหน่อยครับ ว่าต่อจากนี้จะทำยังไง\""),
("\"ยาเบาหวานตัวนั้น ถ้ากินสองมื้อรวมกัน น้ำตาลจะตกตอนกลางดึก เหงื่อแตก มือสั่น ใจสั่น นึกได้ตอนค่ำให้ข้ามไปเลยครับ\"\\n","\"ยาเบาหวานกินสองมื้อรวมกัน น้ำตาลจะตกตอนดึก เหงื่อแตก มือสั่น นึกได้ตอนค่ำให้ข้ามไปเลยครับ\"\\n"),
("เขาแปะกระดาษไว้ข้างเตียง พระอาทิตย์ ชามข้าว พระจันทร์ จุดสีดวงใหญ่ ไม่มีตัวหนังสือเล็กสักตัว\\nเหมือนซองยาเก่าก้นลิ้นชัก ลายมืออาเหมย ซองที่เราทะเลาะกัน","เขาแปะตารางยาข้างเตียง พระอาทิตย์ พระจันทร์ จุดสีดวงใหญ่\\nเหมือนซองยาเก่าลายมืออาเหมย ซองที่เราทะเลาะกัน"),
("\"ยาจะเหลือน้อยกว่านี้ครับ ผมจะเขียนถึงคุณหมอทั้งสี่ท่าน ให้แต่ละท่านรู้ว่ามีอีกสามท่าน\"","\"ผมจะเขียนถึงคุณหมอทั้งสี่ท่าน ยาจะเหลือน้อยกว่านี้ครับ\""),
("\"อาทิตย์หน้าผมมาใหม่นะครับ\" ผมเกือบถามว่า กี่โมง จะได้นั่งรอ\\nประตูปิด ห้องสิบหกตารางเมตรเท่าเดิม แต่ไม่เงียบเท่าเดิม","\"อาทิตย์หน้าผมมาใหม่นะครับ\"\\nประตูปิด ห้องเท่าเดิม แต่ไม่เงียบเท่าเดิม"),
]
for a,b in R:
    assert d.count(a)==1,(a[:70],d.count(a)); d=d.replace(a,b)
# small structural trims: no pill taps on the phone, no second count after the soft-mist puff
x="$('#cimg').src=src('pills_am'); await tapPills(7); $('#cimg').src=src('phone');"; assert d.count(x)==1; d=d.replace(x,"")
x="S.early+=await breathPress()-1; await countHold(5);"; assert d.count(x)==1; d=d.replace(x,"S.early+=await breathPress()-1;")
s=s[:a0]+d+s[b0:]
open(f,'w',encoding='utf-8').write(s); print('day4 condensed')
